"""Small first steps; existing m00 task identifiers and progress remain intact."""
from _dsl import *

ORDER = -10


def lesson(title_, goal, example, tasks):
    return level(title_.split('. ', 1)[-1], goal, [txt('Что научимся делать', p(goal)),
        code('Предскажи вывод, затем запусти', example,
             cond=p('Сначала назови значения переменных и ожидаемый вывод. Затем открой пример в Python или лаборатории.'),
             note='Измени одно число и объясни, почему изменился результат.'),
        txt('Теперь самостоятельно', p('Реши две небольшие задачи. В редакторе есть учебная проверка на разных входных данных. '
            'В поле ответа отправь результат для первого примера из условия. Проверка кода и зачёт ответа — отдельные действия.'))], tasks, need=2)

